-- Offline ProfileStore contract fixture. Studio also tests the real .Mock store.
local MockStore = {}
function MockStore.new(domain)
	local store={records={}, active={}, failBefore=0, failAfter=0}
	local function signal()
		local listeners={}
		return {
			Connect=function(_, fn)
				listeners[fn]=true
				return {Disconnect=function() listeners[fn]=nil end}
			end,
			Fire=function(_, ...)
				for fn in listeners do fn(...) end
			end,
		}
	end
	function store:StartSessionAsync(key)
		if self.active[key] then return nil end
		local profile={Data=domain.copy(self.records[key] or {}), LastSavedData=domain.copy(self.records[key] or {}),
			OnAfterSave=signal(), OnSessionEnd=signal()}
		self.active[key]=profile
		function profile:IsActive() return store.active[key]==self end
		function profile:Save()
			if not self:IsActive() then return end
			if store.onWrite then store.onWrite() end
			if store.failBefore>0 then store.failBefore-=1; return end
			store.records[key]=domain.copy(self.Data)
			if store.failAfter>0 then store.failAfter-=1; return end
			self.LastSavedData=domain.copy(self.Data)
			self.OnAfterSave:Fire(self.LastSavedData)
		end
		function profile:EndSession()
			if self:IsActive() then self:Save(); store.active[key]=nil; self.OnSessionEnd:Fire() end
		end
		return profile
	end
	return store
end
return MockStore

--!strict

--[=[
	@class Spring

	Simulates a critically damped spring. This is mostly just a wrapper around
	[`TweenService:SmoothDamp()`](https://create.roblox.com/docs/reference/engine/classes/TweenService#SmoothDamp).
]=]

local TweenService = game:GetService("TweenService")

local Spring = {}
Spring.__index = Spring

export type Spring<T> = typeof(setmetatable(
	{} :: {
		Current: T,
		Target: T,
		Velocity: T,
		SmoothTime: number,
		MaxSpeed: number,
	},
	Spring
))

--[=[
	Creates a new spring.

	The type `T` can be a `number`, `Vector2`, `Vector3`, or `CFrame`.

	@param initial T -- Initial value
	@param smoothTime number -- Approximate time it takes to reach target
	@param maxSpeed number -- Maximum speed (defaults to infinity)
]=]
function Spring.new<T>(initial: T, smoothTime: number, maxSpeed: number?): Spring<T>
	local self = setmetatable({
		Current = initial,
		Target = initial,
		Velocity = if typeof(initial) == "CFrame" then CFrame.identity else (initial :: any) * 0,
		SmoothTime = smoothTime,
		MaxSpeed = if maxSpeed ~= nil then maxSpeed else math.huge,
	}, Spring)

	return self
end

--[=[
	@within Spring
	@method Update

	Updates the spring. This method should be called continuously, even if the target value hasn't changed.

	```lua
	local newValue = spring:Update(dt)
	```

	@param deltaTime number
	@return T
]=]
function Spring.Update<T>(self: Spring<T>, dt: number): T
	self.Current, self.Velocity =
		TweenService:SmoothDamp(self.Current, self.Target, self.Velocity, self.SmoothTime, self.MaxSpeed, dt)

	return self.Current
end

--[=[
	@within Spring
	@method Impulse

	Impulses the spring.

	```lua
	spring:Impulse(rng:NextUnitVector() * 10)
	```

	@param velocity T
]=]
function Spring.Impulse<T>(self: Spring<T>, velocity: T)
	self.Velocity += velocity :: any
end

--[=[
	@within Spring
	@method Reset

	Resets the spring to the given value.

	@param value T
]=]
function Spring.Reset<T>(self: Spring<T>, value: T)
	self.Current = value
	self.Target = value
	self.Velocity = if typeof(self.Current) == "CFrame" then CFrame.identity else (self.Current :: any) * 0
end

return Spring
